83	/// <summary>API con los adaptadores reales de LLM y el proveedor HTTP falso. Captura los logs de la aplicación.</summary>
84	public sealed class EntornoProveedor : IDisposable
85	{
86	    public const string Llave = "sk-SECRETA-9f3c1a77-no-debe-aparecer";
87	    public const string MarcaProveedor = "CUERPO-INTERNO-DEL-PROVEEDOR-7731";
88	    public const string Url = "/api/asistente/preguntar";
89	
90	    private readonly WebApplicationFactory<Program> _fabrica;
91	    public ProveedorHttpFalso Proveedor { get; } = new();
92	    public LogsEnMemoria Logs { get; } = new();
93	    public HttpClient Cliente { get; }
94	
95	    public EntornoProveedor(string? proveedor, string? llave = Llave, string? baseUrl = null, string? modelo = null)
96	    {
97	        var cfg = new Dictionary<string, string?> { ["Datos:Ruta"] = Fabrica.RutaFixtures, ["LLM_API_KEY"] = llave ?? "" };
98	        if (proveedor != null) cfg["LLM_PROVIDER"] = proveedor;
99	        if (baseUrl != null) cfg["LLM_BASE_URL"] = baseUrl;
100	        if (modelo != null) cfg["LLM_MODEL"] = modelo;
101	
102	        _fabrica = new WebApplicationFactory<Program>().WithWebHostBuilder(b =>
103	        {
104	            foreach (var (k, v) in cfg) b.UseSetting(k, v);
105	            b.ConfigureAppConfiguration((_, c) => c.AddInMemoryCollection(cfg));
106	            b.ConfigureServices(sv => sv.AddLogging(l => { l.SetMinimumLevel(LogLevel.Trace); l.AddProvider(Logs); }));
107	            b.ConfigureTestServices(sv => sv.AddHttpClient("llm").ConfigurePrimaryHttpMessageHandler(() => Proveedor));
108	        });
109	        // CreateClient arranca el host: un valor inválido de LLM_PROVIDER lanza aquí.
110	        Cliente = _fabrica.CreateClient();
111	        Cliente.Timeout = TimeSpan.FromSeconds(60);
112	    }
113	
114	    public async Task<(HttpStatusCode Codigo, string Cuerpo)> Preguntar(string pregunta, string rol = "estudiante", string id = "T-E1")
115	    {
116	        var json = JsonSerializer.Serialize(new { pregunta, usuario = new { rol, id } });
117	        var r = await Cliente.PostAsync(Url, new StringContent(json, Encoding.UTF8, "application/json"));
118	        return (r.StatusCode, await r.Content.ReadAsStringAsync());
119	    }
120	
121	    public void Dispose() { Cliente.Dispose(); _fabrica.Dispose(); }
122	}
