6	public class OpenAiCompatClient(IHttpClientFactory fabrica, IConfiguration cfg) : ILlmClient
7	{
8	    public const string BaseDefecto = "https://generativelanguage.googleapis.com/v1beta/openai";
9	    public const string ModeloDefecto = "gemini-2.5-flash";
10	
11	    public async Task<LlmRespuesta> CompletarAsync(string sistema, IReadOnlyList<LlmMensaje> mensajes,
12	        IReadOnlyList<LlmHerramienta> herramientas, CancellationToken ct)
13	    {
14	        var baseUrl = (string.IsNullOrWhiteSpace(cfg["LLM_BASE_URL"]) ? BaseDefecto : cfg["LLM_BASE_URL"]!).TrimEnd('/');
15	        var modelo = string.IsNullOrWhiteSpace(cfg["LLM_MODEL"]) ? ModeloDefecto : cfg["LLM_MODEL"]!;
16	
17	        var msgs = new JsonArray { new JsonObject { ["role"] = "system", ["content"] = sistema } };
18	        foreach (var m in mensajes)
19	        {
20	            if (m.Rol == "tool")
21	                msgs.Add(new JsonObject { ["role"] = "tool", ["tool_call_id"] = m.ToolCallId, ["content"] = m.Contenido });
22	            else if (m.Rol == "assistant" && m.Llamadas is { Count: > 0 })
23	            {
24	                var calls = new JsonArray();
25	                foreach (var l in m.Llamadas)
26	                    calls.Add(new JsonObject
27	                    {
28	                        ["id"] = l.Id,
29	                        ["type"] = "function",
30	                        ["function"] = new JsonObject { ["name"] = l.Nombre, ["arguments"] = l.ArgumentosJson },
31	                    });
32	                msgs.Add(new JsonObject
33	                {
34	                    ["role"] = "assistant",
35	                    ["content"] = string.IsNullOrEmpty(m.Contenido) ? null : m.Contenido,
36	                    ["tool_calls"] = calls,
37	                });
38	            }
39	            else
40	                msgs.Add(new JsonObject { ["role"] = m.Rol, ["content"] = m.Contenido });
41	        }
42	
43	        var cuerpo = new JsonObject { ["model"] = modelo, ["messages"] = msgs, ["max_tokens"] = 2048 };
44	        if (herramientas.Count > 0)
45	        {
46	            var tools = new JsonArray();
47	            foreach (var h in herramientas)
48	                tools.Add(new JsonObject
49	                {
50	                    ["type"] = "function",
51	                    ["function"] = new JsonObject
52	                    {
53	                        ["name"] = h.Nombre,
54	                        ["description"] = h.Descripcion,
55	                        ["parameters"] = LlmHttp.ParseOVacio(h.ParametrosJsonSchema),
56	                    },
57	                });
58	            cuerpo["tools"] = tools;
59	        }
60	
61	        using var req = new HttpRequestMessage(HttpMethod.Post, $"{baseUrl}/chat/completions");
62	        req.Headers.TryAddWithoutValidation("Authorization", "Bearer " + cfg["LLM_API_KEY"]?.Trim());
63	        using var doc = await LlmHttp.EnviarAsync(fabrica.CreateClient("llm"), req, cuerpo, ct);
64	
65	        try
66	        {
67	            var raiz = doc.RootElement;
68	            var mensaje = raiz.GetProperty("choices")[0].GetProperty("message");
69	            string? texto = mensaje.TryGetProperty("content", out var c) && c.ValueKind == JsonValueKind.String ? c.GetString() : null;
70	            var llamadas = new List<LlmLlamadaHerramienta>();
71	            if (mensaje.TryGetProperty("tool_calls", out var tc) && tc.ValueKind == JsonValueKind.Array)
72	            {
73	                var n = 0;
74	                foreach (var t in tc.EnumerateArray())
75	                {
76	                    var f = t.GetProperty("function");
77	                    var id = t.TryGetProperty("id", out var i) && i.ValueKind == JsonValueKind.String && !string.IsNullOrEmpty(i.GetString())
78	                        ? i.GetString()! : $"call_{n}";
79	                    var args = f.TryGetProperty("arguments", out var a)
80	                        ? (a.ValueKind == JsonValueKind.String ? a.GetString()! : a.GetRawText()) : "{}";
81	                    llamadas.Add(new(id, f.GetProperty("name").GetString()!, string.IsNullOrWhiteSpace(args) ? "{}" : args));
82	                    n++;
83	                }
84	            }
85	            var uso = raiz.TryGetProperty("usage", out var u) ? u : default;
86	            return new(texto, llamadas, new(LlmHttp.Entero(uso, "prompt_tokens"), LlmHttp.Entero(uso, "completion_tokens")));
87	        }
88	        catch (Exception e) when (e is KeyNotFoundException or InvalidOperationException or IndexOutOfRangeException or ArgumentOutOfRangeException)
89	        {
90	            throw new LlmException("El proveedor del modelo devolvió una respuesta sin los campos esperados.");
91	        }
92	    }
93	}
