70	    private static void AssertSinSecretos(EntornoProveedor e, string cuerpoRespuesta)
71	    {
72	        Assert.DoesNotContain(EntornoProveedor.Llave, cuerpoRespuesta);
73	        Assert.DoesNotContain(EntornoProveedor.MarcaProveedor, cuerpoRespuesta);
74	        Assert.DoesNotContain(EntornoProveedor.Llave, e.Logs.Todo);
75	    }
