28	/// <summary>
29	/// API con archivo de auditoría temporal único (Auditoria:Ruta), logs en memoria y, o bien un modelo falso (ILlmClient),
30	/// o bien los adaptadores reales con proveedor HTTP falso. Nunca usa red ni el logs/ del repositorio.
31	/// </summary>
32	public sealed class EntornoAuditoria : IDisposable
33	{
34	    public const string Llave = "sk-AUDITORIA-llave-secreta-5e1b9c42";
35	    public const string Url = "/api/asistente/preguntar";
36	
37	    private readonly WebApplicationFactory<Program> _fabrica;
38	    public string RutaAuditoria { get; }
39	    public HttpClient Cliente { get; }
40	    /// <summary>Servidor en memoria, para peticiones con cuerpo construido a mano (p. ej. un stream que lanza).</summary>
41	    public TestServer Servidor => _fabrica.Server;
42	    public LogsEnMemoria Logs { get; } = new();
43	    public ProveedorHttpFalso Proveedor { get; } = new();
44	
45	    /// <param name="llm">Modelo falso; si es null se usan los adaptadores reales con <see cref="Proveedor"/>.</param>
46	    /// <param name="config">Claves extra de configuración (precios, plazo...).</param>
47	    /// <param name="llave">Valor de LLM_API_KEY ("" = sin llave).</param>
48	    /// <param name="rutaAuditoria">Ruta de auditoría; por defecto un archivo temporal único.</param>
49	    public EntornoAuditoria(ILlmClient? llm, IDictionary<string, string?>? config = null, string llave = Llave,
50	        string? rutaAuditoria = null, Action<IConfigurationBuilder>? configurar = null)
51	    {
52	        RutaAuditoria = rutaAuditoria ?? Path.Combine(Path.GetTempPath(), "tf-audit-" + Guid.NewGuid().ToString("N") + ".jsonl");
53	        var cfg = new Dictionary<string, string?>
54	        {
55	            ["Datos:Ruta"] = Fabrica.RutaFixtures,
56	            ["LLM_API_KEY"] = llave,
57	            ["Auditoria:Ruta"] = RutaAuditoria,
58	        };
59	        if (config != null) foreach (var (k, v) in config) cfg[k] = v;
60	
61	        _fabrica = new WebApplicationFactory<Program>().WithWebHostBuilder(b =>
62	        {
63	            foreach (var (k, v) in cfg) b.UseSetting(k, v);
64	            b.ConfigureAppConfiguration((_, c) => { c.AddInMemoryCollection(cfg); configurar?.Invoke(c); });
65	            b.ConfigureServices(sv => sv.AddLogging(l => { l.SetMinimumLevel(LogLevel.Trace); l.AddProvider(Logs); }));
66	            b.ConfigureTestServices(sv =>
67	            {
68	                sv.AddHttpClient("llm").ConfigurePrimaryHttpMessageHandler(() => (HttpMessageHandler)Proveedor);
69	                if (llm != null)
70	                {
71	                    sv.RemoveAll<ILlmClient>();
72	                    sv.AddSingleton(llm);
73	                }
74	            });
75	        });
76	        // CreateClient arranca el host: una configuración inválida (p. ej. precios) lanza aquí.
77	        Cliente = _fabrica.CreateClient();
78	        Cliente.Timeout = TimeSpan.FromSeconds(60);
79	    }
80	
81	    public async Task<(HttpStatusCode Codigo, string Cuerpo)> Preguntar(string pregunta, string rol, string id,
82	        CancellationToken ct = default)
83	    {
84	        var json = JsonSerializer.Serialize(new { pregunta, usuario = new { rol, id } });
85	        return await Raw(json, ct);
86	    }
87	
88	    public async Task<(HttpStatusCode Codigo, string Cuerpo)> Raw(string json, CancellationToken ct = default)
89	    {
90	        var r = await Cliente.PostAsync(Url, new StringContent(json, Encoding.UTF8, "application/json"), ct);
91	        return (r.StatusCode, await r.Content.ReadAsStringAsync(ct));
92	    }
