94	    /// <summary>Texto completo del archivo de auditoría ("" si no existe).</summary>
95	    public string TextoAuditoria()
96	    {
97	        if (!File.Exists(RutaAuditoria)) return "";
98	        using var fs = new FileStream(RutaAuditoria, FileMode.Open, FileAccess.Read, FileShare.ReadWrite | FileShare.Delete);
99	        using var sr = new StreamReader(fs, Encoding.UTF8);
100	        return sr.ReadToEnd();
101	    }
