103	    /// <summary>Líneas no vacías del archivo; espera hasta <paramref name="msMax"/> a que haya al menos <paramref name="esperadas"/>.</summary>
104	    public async Task<List<string>> LineasCrudas(int esperadas, int msMax = 5000)
105	    {
106	        var fin = DateTime.UtcNow.AddMilliseconds(msMax);
107	        List<string> lineas;
108	        do
109	        {
110	            lineas = TextoAuditoria().Split('\n').Select(l => l.TrimEnd('\r')).Where(l => l.Length > 0).ToList();
111	            if (lineas.Count >= esperadas) break;
112	            await Task.Delay(50);
113	        } while (DateTime.UtcNow < fin);
114	        return lineas;
115	    }
116	
117	    /// <summary>Línea única esperada (falla si hay más o menos de una).</summary>
118	    public async Task<JsonElement> UnaLinea()
119	    {
120	        var l = await LineasCrudas(1);
121	        // Margen para detectar líneas duplicadas escritas tarde.
122	        await Task.Delay(100);
123	        l = await LineasCrudas(1, 0);
124	        Assert.Single(l);
125	        return JsonDocument.Parse(l[0]).RootElement.Clone();
126	    }
