            ["usage"] = new JsonObject { ["input_tokens"] = 7, ["output_tokens"] = 3 },
        }.ToJsonString();

        var conExtra = Guion(ToolUse(Extra(FirmaEspecial)), finalA);
        var sinExtra = Guion(ToolUse(null), finalA);
        using var e1 = new EntornoT6c(conExtra, "anthropic");
