    }

    [Fact]
    public async Task T6c_5c_control_negativo_el_proveedor_falso_si_responde_400_cuando_falta_la_firma_503()
    {
        // Valida que el falso exigente discrimina: un proveedor que firma pero cuyo historial se reenvía sin firma daría 503.
        var prov = new ProveedorFuncion((p, n) =>
        {
            if (n == 1) return Ok(ConLlamadas(("id0", "consultar_notas", "{\"estudianteId\":\"T-E1\"}", Extra("SIG-0/+=="))));
            var calls = p.Json["messages"]!.AsArray().Last(m => (string?)m!["role"] == "assistant")!["tool_calls"]!.AsArray();
            return calls[0]!["extra_content"] == null
                ? new HttpResponseMessage(HttpStatusCode.BadRequest) { Content = new StringContent("{\"error\":\"falta\"}", Encoding.UTF8, "application/json") }
                : Ok(Final());
        });
        using var e = new EntornoT6c(prov);
        var (c, _) = await e.Preguntar("¿Cómo voy en mis notas?");
        // Con el comportamiento correcto el reenvío incluye la firma y no hay 400 del proveedor.
        Assert.Equal(HttpStatusCode.OK, c);
    }

